export const checkTokenExpired = (token) => {

  if (token.length === 0) return false;

  let decoded;
  try { decoded = jwt_decode(token); } catch (e) { console.error('jwt_decode failed in checkTokenExpired:', e.message); return true; }
  let token_expiration = decoded['exp'];
  let currentUtcSeconds = Math.floor(Date.now() / 1000);
  let token_expired = currentUtcSeconds > token_expiration ? true : false;

  return token_expired;
}
