// creates a list of times throughtout the day seperated by 30 minutes each for use by a selectbox
export const getAllEventTimes = () => {
  const times = [];
  let date = new Date();
  date.setHours(0, 0, 0, 0); // set the time to the start of the day
  const startTime = date.getTime(); // get the start time in milliseconds
  const halfHour = 30 * 60 * 1000; // 30 minutes in milliseconds

  for (let i = 0; i < 48; i++) { // 48 half hours in a day
    let time = new Date(startTime + i * halfHour);
    let hours = time.getHours();
    let minutes = time.getMinutes();
    let amPm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12;
    minutes = minutes < 10 ? '0' + minutes : minutes;
    let formattedTime = hours + ':' + minutes + amPm;
    times.push({ id: i, value: formattedTime, label: formattedTime });
  }

  return (times);

}
