// returns either 'P' for premium or 'F' for free
export const userAccessToSelectedSecurity = (securityTypeList2, selectedSecurity) => {

  var rtype = '';
  var count_free = 0;
  var count_prem = 0;


  for (let i = 0; i < securityTypeList2.length; i++) {
    if (selectedSecurity === securityTypeList2[i]['label']) {
      rtype = securityTypeList2[i]['type'];
    }
    if (securityTypeList2[i]['type'] === 'P') count_prem += 1;
    if (securityTypeList2[i]['type'] === 'F') count_free += 1;
  }

  return [rtype, count_prem, count_free];

}
//-------------------------------------------------------------------------------------------------------------------------------------
export const getSelectedIDFromSecuritiesList2 = (securityTypeList, selectedSecurity) => {

  for (var i = 0; i < securityTypeList.length; i++) {
    if (securityTypeList[i]['value'] === selectedSecurity) {
      return securityTypeList[i]['id'];
    }
  }

  return -1; // not found
}
