export const ratelimitMessage = (trigger, userid) => {

  let msg = 'The number of requests allowed by the server of ' + String(trigger) + ' has been exceeded. '

  // console.log('ratelimitMessage:', ratelimitMessage)

  if (trigger.includes('per 1 second')) {
    msg += 'please click slower.'
  }
  else if (trigger.includes('per 1 minute')) {
    msg += 'Wait for a minute to try your search.'
  }
  else if (trigger.includes('per 1 hour')) {
    msg += 'Try your search in an hour.'
  }
  else if (trigger.includes('per 1 day')) {
    msg += 'You can try again tomorrow.'
  }

  return msg;


}
