// Merged resource families: securities groups whose symbols overlap
// US Stocks: DOW 30(0), NASDAQ 100(1), S&P 500(2), RUSSELL 1000(3), WILSHIRE 5000(4)
// Indices: INDICES COMMON(5), INDICES ALL(6)
// Forex: FOREX LIQUID(9), FOREX ALL(8)
const mergedFamilies = [[0, 1, 2, 3, 4], [5, 6], [8, 9]];
export const sameResourceFamily = (idA, idB) => {
  if (idA === idB) return true;
  return mergedFamilies.some(f => f.includes(idA) && f.includes(idB));
}

