//-------------------------------------------------------------------------------------------
export   function daysBetweenDates(date0, date1) { //increment date in format of yyyy-mm-dd and return same format

  const date1Obj = new Date(date1);
  const date0Obj = new Date(date0);

  // Calculate the time difference in milliseconds
  const timeDifference = date1Obj - date0Obj;

  // Convert milliseconds to days (1 day = 24 hours * 60 minutes * 60 seconds * 1000 milliseconds)
  const daysDifference = Math.floor(timeDifference / (24 * 60 * 60 * 1000));

  return Math.abs(daysDifference);

}
//-------------------------------------------------------------------------------------------
export const getTodayDate = () => {
  var today = new Date();
  var dd = String(today.getDate()).padStart(2, '0');
  var mm = String(today.getMonth() + 1).padStart(2, '0'); //January is 0!
  var yyyy = today.getFullYear();

  if (mm === '02' && dd === '29') { // no leap in this - increment by 1 day
    return `${yyyy}-03-01`
  }

  return `${yyyy}-${mm}-${dd}`
}
//-------------------------------------------------------------------------------------------
export const getCookie = (name) => {
  var nameEQ = name + "=";
  var ca = document.cookie.split(';');
  for (var i = 0; i < ca.length; i++) {
    var c = ca[i];
    while (c.charAt(0) === ' ') c = c.substring(1, c.length);
    if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length, c.length);
  }
  return null;
}
//-------------------------------------------------------------------------------------------
export const setCookie = (name, value, days) => {
  var expires = "";
  if (days) {
    var date = new Date();
    date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
    expires = "; expires=" + date.toUTCString();
  }
  // document.cookie = name + "=" + (value || "") + expires + "; path=/";
  const isSecure = window.location.protocol === 'https:';
  const cookieSettings = `${name}=${value || ""}${expires}; path=/; SameSite=Lax${isSecure ? '; Secure' : ''}`;
  document.cookie = cookieSettings;
}
