export const cumulativeReturn = (seasonalBarChartData, barChartLongOrShort) => {

  var cdata = []
  var cdataL = []
  var cr = 1
  for (var i = 0; i < seasonalBarChartData.length; i++) {
    var pct = parseFloat(seasonalBarChartData[i]['pct'].split(',')[0] / 100) // each data point in float

    // console.log('pct=', pct, i, seasonalBarChartData.length - 1)


    if (barChartLongOrShort === 'short') pct = -1 * pct;
    cr *= (1 + pct)

    if (i === seasonalBarChartData.length - 1 && pct === 0) {
      // condition is for last year that hasn't started yet 
      // don't add it for cumulative return calculation 5/27/2022

    }
    else {
      cdata.push((cr * 100) - 100)
      cdataL.push(seasonalBarChartData[i]['year'])
    }
  }

  return {
    cdata: cdata,
    cdataL: cdataL
  }

}
